size_t hashes[2];
const void *key = *reinterpret_cast<const void**>(&key);
const void *data = *reinterpret_cast<const void**>(&data);

ckh->hash(key, hashes);

size_t bucket = hashes[0] & ((std::size_t(1) << ckh->lg_curbuckets) - 1);
if (!ckh_try_bucket_insert(ckh, bucket, key, data)) {
    return false;
}

bucket = hashes[1] & ((std::size_t(1) << ckh->lg_curbuckets) - 1);
if (!ckh_try_bucket_insert(ckh, bucket, key, data)) {
    return false;
}

return ckh_evict_reloc_insert(ckh, bucket, &key, &data);

